"use client"

import React from "react"
import * as AccordionPrimitive from "@radix-ui/react-accordion"
import { type VariantProps, cva } from "class-variance-authority"
import { ChevronDownIcon, Plus } from "lucide-react"
import { cn as classNames } from "@/lib/utils"

// Defining the types for the accordion
export type AccordionContextType = {
	size?: VariantProps<typeof accordionVariants>["size"]
	variant?: VariantProps<typeof accordionVariants>["variant"]
	indicator?: VariantProps<typeof accordionTriggerVariants>["indicator"]
}

export type AccordionProps = React.ComponentProps<
	typeof AccordionPrimitive.Root
> &
	VariantProps<typeof accordionVariants> & {
		indicator?: VariantProps<typeof accordionTriggerVariants>["indicator"]
	}

export type AccordionItemProps = React.ComponentProps<
	typeof AccordionPrimitive.Item
>

export type AccordionTriggerProps = React.ComponentProps<
	typeof AccordionPrimitive.Trigger
>

export type AccordionContentProps = React.ComponentProps<
	typeof AccordionPrimitive.Content
>

const AccordionContext = React.createContext<AccordionContextType | null>(null)

// Defining the different variants for the accordion
const accordionVariants = cva("w-full", {
	variants: {
		size: {
			sm: "text-sm/6",
			lg: "text-base/7",
		},
		variant: {
			box: "",
			table: "border-stroke rounded-xl border",
			open: "",
		},
	},
	defaultVariants: {
		size: "sm",
		variant: "box",
	},
})

const accordionItemVariants = cva("overflow-hidden", {
	variants: {
		variant: {
			box: "border-stroke border shadow-2xs rounded-lg last:mb-0",
			table: "border-b first:rounded-t-xl last:rounded-b-xl last:border-b-0",
			open: "border-b last:border-b-0",
		},
		size: {
			sm: "",
			lg: "",
		},
	},
	compoundVariants: [
		{
			variant: "box",
			size: "sm",
			class: "mb-1.5",
		},
		{
			variant: "box",
			size: "lg",
			class: "mb-2",
		},
	],
	defaultVariants: {
		variant: "box",
		size: "sm",
	},
})

const accordionTriggerVariants = cva(
	"text-fg outline-hidden flex flex-1 cursor-pointer items-center justify-between text-left font-medium transition-all",
	{
		variants: {
			variant: {
				box: "",
				table: "",
				open: "",
			},
			size: {
				sm: "leading-5",
				lg: "leading-6",
			},
			indicator: {
				chevron: "[&[data-state=open]>.AccordionChevron]:rotate-180",
				"plus-minus":
					"[&[data-state=open]>.AccordionPlus>path:last-child]:rotate-90 [&[data-state=open]>.AccordionPlus>path:last-child]:opacity-0 [&[data-state=open]>.AccordionPlus]:rotate-180",
			},
		},
		compoundVariants: [
			{
				variant: "open",
				size: "sm",
				class: "px-0 py-3",
			},
			{
				variant: "open",
				size: "lg",
				class: "px-0 py-4",
			},
			{
				variant: ["box", "table"],
				size: "sm",
				class: "p-3",
			},
			{
				variant: ["box", "table"],
				size: "lg",
				class: "p-4",
			},
			// Indicator sizing
			{
				indicator: ["chevron", "plus-minus"],
				size: "sm",
				class: "[&>.AccordionChevron]:size-5 [&>.AccordionPlus]:size-5",
			},
			{
				indicator: ["chevron", "plus-minus"],
				size: "lg",
				class: "[&>.AccordionChevron]:size-6 [&>.AccordionPlus]:size-6",
			},
		],
		defaultVariants: {
			variant: "box",
			size: "sm",
			indicator: "chevron",
		},
	}
)

const accordionContentVariants = cva(
	"text-fg-secondary data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down overflow-hidden transition-all"
)

const accordionContentInnerVariants = cva("pt-0", {
	variants: {
		variant: {
			box: "",
			table: "",
			open: "",
		},
		size: {
			sm: "",
			lg: "",
		},
	},
	compoundVariants: [
		{
			variant: "open",
			size: "sm",
			class: "px-0 pb-3",
		},
		{
			variant: "open",
			size: "lg",
			class: "px-0 pb-4",
		},
		{
			variant: ["box", "table"],
			size: "sm",
			class: "px-3 pb-3",
		},
		{
			variant: ["box", "table"],
			size: "lg",
			class: "px-4 pb-4",
		},
	],
	defaultVariants: {
		variant: "box",
		size: "sm",
	},
})

// Defining the hook for the accordion
function useAccordion() {
	const context = React.useContext(AccordionContext)
	if (!context) {
		throw new Error("useAccordion must be used within a <Accordion />")
	}
	return context
}

/* Define the components */
function Accordion({
	size = "sm",
	variant = "box",
	indicator = "chevron",
	className,
	children,
	...props
}: AccordionProps) {
	return (
		<AccordionContext.Provider
			value={{
				size: size ?? "sm",
				variant: variant ?? "box",
				indicator: indicator ?? "chevron",
			}}>
			<AccordionPrimitive.Root
				data-slot="accordion"
				className={classNames(accordionVariants({ size, variant }), className)}
				{...props}>
				{children}
			</AccordionPrimitive.Root>
		</AccordionContext.Provider>
	)
}
Accordion.displayName = "Accordion"

function AccordionItem({ children, className, ...props }: AccordionItemProps) {
	const { variant, size } = useAccordion()

	return (
		<AccordionPrimitive.Item
			data-slot="accordion-item"
			className={classNames(
				accordionItemVariants({ variant, size }),
				className
			)}
			{...props}>
			{children}
		</AccordionPrimitive.Item>
	)
}

AccordionItem.displayName = "AccordionItem"

function AccordionTrigger({
	children,
	className,
	...props
}: AccordionTriggerProps) {
	const { size, variant, indicator } = useAccordion()

	return (
		<AccordionPrimitive.Header className="flex">
			<AccordionPrimitive.Trigger
				data-slot="accordion-trigger"
				className={classNames(
					accordionTriggerVariants({ variant, size, indicator }),
					className
				)}
				{...props}>
				{children}
				{indicator === "chevron" && (
					<ChevronDownIcon
						className="AccordionChevron text-fg-tertiary shrink-0 transition-transform duration-200"
						aria-hidden
					/>
				)}
				{indicator === "plus-minus" && (
					<Plus
						className="AccordionPlus text-fg-tertiary shrink-0 transition-transform duration-200"
						aria-hidden
					/>
				)}
			</AccordionPrimitive.Trigger>
		</AccordionPrimitive.Header>
	)
}

AccordionTrigger.displayName = "AccordionTrigger"

function AccordionContent({
	children,
	className,
	...props
}: AccordionContentProps) {
	const { size, variant } = useAccordion()

	return (
		<AccordionPrimitive.Content
			data-slot="accordion-content"
			className={classNames(accordionContentVariants())}
			{...props}>
			<div
				className={classNames(
					accordionContentInnerVariants({ variant, size }),
					className
				)}>
				{children}
			</div>
		</AccordionPrimitive.Content>
	)
}

AccordionContent.displayName = "AccordionContent"

/* Export all components*/
export { Accordion, AccordionContent, AccordionItem, AccordionTrigger }

import * as React from "react"
import * as AlertDialogPrimitive from "@radix-ui/react-alert-dialog"
import { type VariantProps, cva } from "class-variance-authority"
import { cn } from "@/lib/utils"

export type Backdrop = VariantProps<
	typeof alertDialogOverlayVariants
>["backdrop"]
export type AlertDialogProps = React.ComponentProps<
	typeof AlertDialogPrimitive.Root
>
export type AlertDialogTriggerProps = React.ComponentProps<
	typeof AlertDialogPrimitive.Trigger
>
export type AlertDialogPortalProps = React.ComponentProps<
	typeof AlertDialogPrimitive.Portal
>
export type AlertDialogOverlayProps = React.ComponentProps<
	typeof AlertDialogPrimitive.Overlay
> & { backdrop?: Backdrop }
export type AlertDialogContentProps = React.ComponentProps<
	typeof AlertDialogPrimitive.Content
> & { backdrop?: Backdrop }
export type AlertDialogHeaderProps = React.HTMLAttributes<HTMLDivElement>
export type AlertDialogFooterProps = React.HTMLAttributes<HTMLDivElement>
export type AlertDialogTitleProps = React.ComponentProps<
	typeof AlertDialogPrimitive.Title
>
export type AlertDialogDescriptionProps = React.ComponentProps<
	typeof AlertDialogPrimitive.Description
>
export type AlertDialogActionProps = React.ComponentProps<
	typeof AlertDialogPrimitive.Action
>
export type AlertDialogCancelProps = React.ComponentProps<
	typeof AlertDialogPrimitive.Cancel
>

export const alertDialogOverlayVariants = cva(
	"data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 fixed inset-0 z-50",
	{
		variants: {
			backdrop: {
				overlay: "bg-black/50",
				blur: "backdrop-blur-md bg-black/25",
				transparent: "bg-transparent",
			},
		},
		defaultVariants: {
			backdrop: "overlay",
		},
	}
)

function AlertDialog({ ...props }: AlertDialogProps) {
	return <AlertDialogPrimitive.Root data-slot="alert-dialog" {...props} />
}
AlertDialog.displayName = AlertDialogPrimitive.Root.displayName

function AlertDialogTrigger({ ...props }: AlertDialogTriggerProps) {
	return (
		<AlertDialogPrimitive.Trigger data-slot="alert-dialog-trigger" {...props} />
	)
}
AlertDialogTrigger.displayName = AlertDialogPrimitive.Trigger.displayName

function AlertDialogPortal({ ...props }: AlertDialogPortalProps) {
	return (
		<AlertDialogPrimitive.Portal data-slot="alert-dialog-portal" {...props} />
	)
}
AlertDialogPortal.displayName = AlertDialogPrimitive.Portal.displayName

function AlertDialogOverlay({
	className,
	backdrop = "overlay",
	...props
}: AlertDialogOverlayProps) {
	return (
		<AlertDialogPrimitive.Overlay
			data-slot="alert-dialog-overlay"
			className={cn(alertDialogOverlayVariants({ backdrop }), className)}
			{...props}
		/>
	)
}
AlertDialogOverlay.displayName = AlertDialogPrimitive.Overlay.displayName

function AlertDialogContent({
	className,
	backdrop,
	...props
}: AlertDialogContentProps) {
	return (
		<AlertDialogPortal>
			<AlertDialogOverlay backdrop={backdrop} />
			<AlertDialogPrimitive.Content
				data-slot="alert-dialog-content"
				className={cn(
					"bg-bg data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 border-alpha fixed left-[50%] top-[50%] z-50 grid w-full max-w-lg translate-x-[-50%] translate-y-[-50%] gap-5 rounded-xl border p-6 shadow-lg shadow-black/5 duration-200",
					className
				)}
				{...props}
			/>
		</AlertDialogPortal>
	)
}
AlertDialogContent.displayName = AlertDialogPrimitive.Content.displayName

function AlertDialogHeader({ className, ...props }: AlertDialogHeaderProps) {
	return (
		<div
			data-slot="alert-dialog-header"
			className={cn(
				"flex flex-col space-y-1 text-center sm:text-left",
				className
			)}
			{...props}
		/>
	)
}
AlertDialogHeader.displayName = "AlertDialogHeader"

function AlertDialogFooter({ className, ...props }: AlertDialogFooterProps) {
	return (
		<div
			data-slot="alert-dialog-footer"
			className={cn(
				"flex flex-col-reverse gap-2 sm:flex-row sm:justify-end",
				className
			)}
			{...props}
		/>
	)
}
AlertDialogFooter.displayName = "AlertDialogFooter"

function AlertDialogTitle({ className, ...props }: AlertDialogTitleProps) {
	return (
		<AlertDialogPrimitive.Title
			data-slot="alert-dialog-title"
			className={cn("text-lg font-semibold", className)}
			{...props}
		/>
	)
}
AlertDialogTitle.displayName = AlertDialogPrimitive.Title.displayName

function AlertDialogDescription({
	className,
	...props
}: AlertDialogDescriptionProps) {
	return (
		<AlertDialogPrimitive.Description
			data-slot="alert-dialog-description"
			className={cn("text-fg-secondary text-sm", className)}
			{...props}
		/>
	)
}
AlertDialogDescription.displayName =
	AlertDialogPrimitive.Description.displayName

function AlertDialogAction({ ...props }: AlertDialogActionProps) {
	return (
		<AlertDialogPrimitive.Action data-slot="alert-dialog-action" {...props} />
	)
}
AlertDialogAction.displayName = AlertDialogPrimitive.Action.displayName

function AlertDialogCancel({ ...props }: AlertDialogCancelProps) {
	return (
		<AlertDialogPrimitive.Cancel data-slot="alert-dialog-cancel" {...props} />
	)
}
AlertDialogCancel.displayName = AlertDialogPrimitive.Cancel.displayName

export {
	AlertDialog,
	AlertDialogTrigger,
	AlertDialogHeader,
	AlertDialogTitle,
	AlertDialogContent,
	AlertDialogPortal,
	AlertDialogOverlay,
	AlertDialogDescription,
	AlertDialogFooter,
	AlertDialogAction,
	AlertDialogCancel,
}

import * as React from "react"
import { type VariantProps, cva } from "class-variance-authority"
import { X } from "lucide-react"
import { cn } from "@/lib/utils"

export type AlertProps = Omit<
	React.HTMLAttributes<HTMLDivElement>,
	"color" | "variant"
> &
	VariantProps<typeof alertVariants> & {
		close?: boolean
		onClose?: () => void
	}

export type AlertTitleProps = React.HTMLAttributes<HTMLHeadingElement>
export type AlertDescriptionProps = React.HTMLAttributes<HTMLParagraphElement>
export type AlertContentProps = React.HTMLAttributes<HTMLDivElement>
export type AlertIconProps = React.HTMLAttributes<HTMLDivElement>
export type AlertToolbarProps = React.HTMLAttributes<HTMLDivElement>

const alertVariants = cva(
	"flex items-stretch w-full gap-3 p-3 rounded-lg [&>[data-slot=alert-title]]:font-medium [&>[data-slot=alert-title]]:text-sm [&>[data-slot=alert-title]]:mt-0.75 [&>[data-slot=alert-description]]:text-sm  [&>[data-slot=alert-icon]>svg]:size-5 [&_[data-slot=alert-icon]]:mt-0.75 [&_[data-slot=alert-close]]:mt-0.75",
	{
		variants: {
			color: {
				neutral: "",
				primary: "",
				info: "",
				success: "",
				error: "",
				warning: "",
			},
			variant: {
				strong: "",
				soft: "[&_[data-slot=alert-title]]:text-fg [&_[data-slot=alert-description]]:text-fg",
				"soft-outline":
					"ring-1 ring-inset [&_[data-slot=alert-title]]:text-fg [&_[data-slot=alert-description]]:text-fg",
				outline:
					"border border-soft [&_[data-slot=alert-close]]:text-fg-tertiary [&_[data-slot=alert-title]]:text-fg [&_[data-slot=alert-description]]:text-fg",
			},
		},
		compoundVariants: [
			// Soft variants
			{ color: "neutral", variant: "soft", className: "bg-fill2" },
			{
				color: "primary",
				variant: "soft",
				className: "bg-primary-accent text-primary-text",
			},
			{
				color: "info",
				variant: "soft",
				className: "bg-info-accent text-info-text",
			},
			{
				color: "success",
				variant: "soft",
				className: "bg-success-accent text-success-text",
			},
			{
				color: "error",
				variant: "soft",
				className: "bg-error-accent text-error-text",
			},
			{
				color: "warning",
				variant: "soft",
				className: "bg-warning-accent text-warning-text",
			},

			// Strong variants
			{
				color: "neutral",
				variant: "strong",
				className: "bg-black-inverse text-white-inverse",
			},
			{
				color: "primary",
				variant: "strong",
				className: "bg-primary text-white",
			},
			{ color: "info", variant: "strong", className: "bg-info text-white" },
			{
				color: "warning",
				variant: "strong",
				className: "bg-warning text-white",
			},
			{ color: "error", variant: "strong", className: "bg-error text-white" },
			{
				color: "success",
				variant: "strong",
				className: "bg-success text-white",
			},

			// Soft-outline variants
			{
				color: "neutral",
				variant: "soft-outline",
				className: "border-border bg-fill2",
			},
			{
				color: "primary",
				variant: "soft-outline",
				className: "bg-primary-accent text-primary-text border-primary-border",
			},
			{
				color: "info",
				variant: "soft-outline",
				className: "bg-info-accent text-info-text border-info-border",
			},
			{
				color: "success",
				variant: "soft-outline",
				className: "bg-success-accent text-success-text border-success-border",
			},
			{
				color: "error",
				variant: "soft-outline",
				className: "bg-error-accent text-error-text border-error-border",
			},
			{
				color: "warning",
				variant: "soft-outline",
				className: "bg-warning-accent text-warning-text border-warning-border",
			},

			// Outline variants
			{
				color: "neutral",
				variant: "outline",
				className: "bg-transparent text-fg ",
			},
			{
				color: "primary",
				variant: "outline",
				className: "bg-transparent text-primary-text",
			},
			{
				color: "info",
				variant: "outline",
				className: "bg-transparent text-info-text",
			},
			{
				color: "success",
				variant: "outline",
				className: "bg-transparent text-success-text",
			},
			{
				color: "error",
				variant: "outline",
				className: "bg-transparent text-error-text",
			},
			{
				color: "warning",
				variant: "outline",
				className: "bg-transparent text-warning-text",
			},
		],
		defaultVariants: {
			color: "primary",
			variant: "soft",
		},
	}
)

function Alert({
	className,
	color = "primary",
	variant = "soft",
	close = false,
	onClose,
	children,
	...props
}: AlertProps) {
	return (
		<div
			data-slot="alert"
			role="alert"
			className={cn(alertVariants({ color, variant }), className)}
			{...props}>
			{children}
			{close && (
				<button
					onClick={onClose}
					aria-label="Dismiss"
					data-slot="alert-close"
					className={cn(
						"group flex size-5 shrink-0 cursor-pointer items-center justify-center"
					)}>
					<X className="size-4 opacity-60 group-hover:opacity-100" />
				</button>
			)}
		</div>
	)
}

Alert.displayName = "Alert"

function AlertTitle({ className, ...props }: AlertTitleProps) {
	return (
		<div data-slot="alert-title" className={cn("grow", className)} {...props} />
	)
}

AlertTitle.displayName = "AlertTitle"

function AlertIcon({ children, className, ...props }: AlertIconProps) {
	return (
		<div
			data-slot="alert-icon"
			className={cn("shrink-0", className)}
			{...props}>
			{children}
		</div>
	)
}
AlertIcon.displayName = "AlertIcon"

function AlertToolbar({ children, className, ...props }: AlertToolbarProps) {
	return (
		<div data-slot="alert-toolbar" className={cn(className)} {...props}>
			{children}
		</div>
	)
}
AlertToolbar.displayName = "AlertToolbar"

function AlertDescription({ className, ...props }: AlertDescriptionProps) {
	return (
		<div
			data-slot="alert-description"
			className={cn("text-sm [&_p]:mb-2 [&_p]:leading-relaxed", className)}
			{...props}
		/>
	)
}
AlertDescription.displayName = "AlertDescription"

function AlertContent({ className, ...props }: AlertContentProps) {
	return (
		<div
			data-slot="alert-content"
			className={cn(
				"flex grow flex-col justify-center gap-1 [&>[data-slot=alert-description]]:text-sm [&>[data-slot=alert-title]]:text-sm [&>[data-slot=alert-title]]:font-medium",
				className
			)}
			{...props}
		/>
	)
}
AlertContent.displayName = "AlertContent"

export {
	Alert,
	AlertContent,
	AlertDescription,
	AlertIcon,
	AlertTitle,
	AlertToolbar,
	alertVariants,
}

import { AspectRatio as AspectRatioPrimitive } from "@radix-ui/react-aspect-ratio"
import { cn } from "@/lib/utils"

export type AspectRatioProps = React.ComponentProps<typeof AspectRatioPrimitive>

function AspectRatio({ className, ...props }: AspectRatioProps) {
	return (
		<AspectRatioPrimitive
			data-slot="aspect-ratio"
			className={cn("", className)}
			{...props}
		/>
	)
}

AspectRatio.displayName = "AspectRatio"

export { AspectRatio }

"use client"

import React, { createContext, useContext } from "react"
import * as AvatarPrimitive from "@radix-ui/react-avatar"
import { type VariantProps, cva } from "class-variance-authority"
import { cn } from "@/lib/utils"

export type AvatarProps = React.ComponentProps<typeof AvatarPrimitive.Root> & {
	size?: NonNullable<VariantProps<typeof avatarVariants>["size"]>
	rounded?: NonNullable<VariantProps<typeof avatarVariants>["rounded"]>
}
export type AvatarImageProps = React.ComponentProps<
	typeof AvatarPrimitive.Image
>
export type AvatarFallbackProps = React.ComponentProps<
	typeof AvatarPrimitive.Fallback
>
export type AvatarIndicatorProps = React.HTMLAttributes<HTMLDivElement>
export type AvatarStatusProps = React.HTMLAttributes<HTMLDivElement> &
	VariantProps<typeof avatarStatusVariants>

export type AvatarContextValue = {
	size: NonNullable<VariantProps<typeof avatarVariants>["size"]>
}

const AvatarContext = createContext<AvatarContextValue | null>(null)

function useAvatarContext() {
	const context = useContext(AvatarContext)
	if (!context) {
		throw new Error("Avatar components must be used within an Avatar")
	}
	return context
}

const avatarVariants = cva(
	"flex items-center font-semibold justify-center shrink-0 relative",
	{
		variants: {
			size: {
				"16": "size-4 text-xs",
				"20": "size-5 text-xs",
				"24": "size-6 text-xs",
				"32": "size-8 text-sm",
				"36": "size-9 text-sm",
				"40": "size-10 text-sm",
				"48": "size-12 text-base",
				"64": "size-16 text-xl",
				"80": "size-20 text-2xl",
			},
			rounded: {
				circle: "rounded-full",
				square: "",
			},
		},
		compoundVariants: [
			{ size: "16", rounded: "square", class: "rounded-sm" },
			{ size: "20", rounded: "square", class: "rounded-sm" },
			{ size: "24", rounded: "square", class: "rounded-md" },
			{ size: "32", rounded: "square", class: "rounded-md" },
			{ size: "36", rounded: "square", class: "rounded-lg" },
			{ size: "40", rounded: "square", class: "rounded-lg" },
