					fileToRemove &&
					fileToRemove.preview &&
					fileToRemove.file instanceof File &&
					fileToRemove.file.type.startsWith("image/")
				) {
					URL.revokeObjectURL(fileToRemove.preview)
				}

				const newFiles = prev.files.filter(function (file) {
					return file.id !== id
				})
				onFilesChange?.(newFiles)

				return {
					...prev,
					files: newFiles,
					errors: [],
				}
			})
		},
		[onFilesChange]
	)

	const clearErrors = useCallback(function () {
		setState(function (prev) {
			return {
				...prev,
				errors: [],
			}
		})
	}, [])

	const handleDragEnter = useCallback(function (e: DragEvent<HTMLElement>) {
		e.preventDefault()
		e.stopPropagation()
		setState(function (prev) {
			return { ...prev, isDragging: true }
		})
	}, [])

	const handleDragLeave = useCallback(function (e: DragEvent<HTMLElement>) {
		e.preventDefault()
		e.stopPropagation()

		if (e.currentTarget.contains(e.relatedTarget as Node)) {
			return
		}

		setState(function (prev) {
			return { ...prev, isDragging: false }
		})
	}, [])

	const handleDragOver = useCallback(function (e: DragEvent<HTMLElement>) {
		e.preventDefault()
		e.stopPropagation()
	}, [])

	const handleDrop = useCallback(
		function (e: DragEvent<HTMLElement>) {
			e.preventDefault()
			e.stopPropagation()
			setState(function (prev) {
				return { ...prev, isDragging: false }
			})

			// Don't process files if the input is disabled
			if (inputRef.current?.disabled) {
				return
			}

			if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
				// In single file mode, only use the first file
				if (!multiple) {
					const file = e.dataTransfer.files[0]
					addFiles([file])
				} else {
					addFiles(e.dataTransfer.files)
				}
			}
		},
		[addFiles, multiple]
	)

	const handleFileChange = useCallback(
		function (e: ChangeEvent<HTMLInputElement>) {
			if (e.target.files && e.target.files.length > 0) {
				addFiles(e.target.files)
			}
		},
		[addFiles]
	)

	const openFileDialog = useCallback(function () {
		if (inputRef.current) {
			inputRef.current.click()
		}
	}, [])

	const getInputProps = useCallback(
		function (props: InputHTMLAttributes<HTMLInputElement> = {}) {
			return {
				...props,
				type: "file" as const,
				onChange: handleFileChange,
				accept: props.accept || accept,
				multiple: props.multiple !== undefined ? props.multiple : multiple,
				ref: inputRef,
			}
		},
		[accept, multiple, handleFileChange]
	)

	return [
		state,
		{
			addFiles,
			removeFile,
			clearFiles,
			clearErrors,
			handleDragEnter,
			handleDragLeave,
			handleDragOver,
			handleDrop,
			handleFileChange,
			openFileDialog,
			getInputProps,
		},
	]
}

// Helper function to format bytes to human-readable format
export function formatBytes(bytes: number, decimals = 2): string {
	if (bytes === 0) return "0 Bytes"

	const k = 1024
	const dm = decimals < 0 ? 0 : decimals
	const sizes = ["Bytes", "KB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB"]

	const i = Math.floor(Math.log(bytes) / Math.log(k))

	return Number.parseFloat((bytes / k ** i).toFixed(dm)) + sizes[i]
}

